212	    /**
213	     Create a new, empty safelist. Generally it will be better to start with a default prepared safelist instead.
214	
215	     @see #basic()
216	     @see #basicWithImages()
217	     @see #simpleText()
218	     @see #relaxed()
219	     */
220	    public Safelist() {
221	        tagNames = new HashSet<>();
222	        attributes = new HashMap<>();
223	        enforcedAttributes = new HashMap<>();
224	        protocols = new HashMap<>();
225	        preserveRelativeLinks = false;
226	    }
