228	    /**
229	     Deep copy an existing Safelist to a new Safelist.
230	     @param copy the Safelist to copy
231	     */
232	    public Safelist(Safelist copy) {
233	        this();
234	        tagNames.addAll(copy.tagNames);
235	        for (Map.Entry<TagName, Set<AttributeKey>> copyTagAttributes : copy.attributes.entrySet()) {
236	            attributes.put(copyTagAttributes.getKey(), new HashSet<>(copyTagAttributes.getValue()));
237	        }
238	        for (Map.Entry<TagName, Map<AttributeKey, AttributeValue>> enforcedEntry : copy.enforcedAttributes.entrySet()) {
239	            enforcedAttributes.put(enforcedEntry.getKey(), new HashMap<>(enforcedEntry.getValue()));
240	        }
241	        for (Map.Entry<TagName, Map<AttributeKey, Set<Protocol>>> protocolsEntry : copy.protocols.entrySet()) {
242	            Map<AttributeKey, Set<Protocol>> attributeProtocolsCopy = new HashMap<>();
243	            for (Map.Entry<AttributeKey, Set<Protocol>> attributeProtocols : protocolsEntry.getValue().entrySet()) {
244	                attributeProtocolsCopy.put(attributeProtocols.getKey(), new HashSet<>(attributeProtocols.getValue()));
245	            }
246	            protocols.put(protocolsEntry.getKey(), attributeProtocolsCopy);
247	        }
248	        preserveRelativeLinks = copy.preserveRelativeLinks;
249	    }
