291	    /**
292	     Add a list of allowed attributes to a tag. (If an attribute is not allowed on an element, it will be removed.)
293	     <p>
294	     E.g.: <code>addAttributes("a", "href", "class")</code> allows <code>href</code> and <code>class</code> attributes
295	     on <code>a</code> tags.
296	     </p>
297	     <p>
298	     To make an attribute valid for <b>all tags</b>, use the pseudo tag <code>:all</code>, e.g.
299	     <code>addAttributes(":all", "class")</code>.
300	     </p>
301	
302	     @param tag  The tag the attributes are for. The tag will be added to the allowed tag list if necessary.
303	     @param attributes List of valid attributes for the tag
304	     @return this (for chaining)
305	     */
306	    public Safelist addAttributes(String tag, String... attributes) {
307	        Validate.notEmpty(tag);
308	        Validate.notNull(attributes);
309	        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");
310	
311	        addTags(tag);
312	        TagName tagName = TagName.valueOf(tag);
313	        Set<AttributeKey> attributeSet = new HashSet<>();
314	        for (String key : attributes) {
315	            Validate.notEmpty(key);
316	            attributeSet.add(AttributeKey.valueOf(key));
317	        }
318	        Set<AttributeKey> currentSet = this.attributes.computeIfAbsent(tagName, k -> new HashSet<>());
319	        currentSet.addAll(attributeSet);
320	        return this;
321	    }
322	
323	    /**
324	     Remove a list of allowed attributes from a tag. (If an attribute is not allowed on an element, it will be removed.)
325	     <p>
326	     E.g.: <code>removeAttributes("a", "href", "class")</code> disallows <code>href</code> and <code>class</code>
327	     attributes on <code>a</code> tags.
328	     </p>
329	     <p>
330	     To make an attribute invalid for <b>all tags</b>, use the pseudo tag <code>:all</code>, e.g.
331	     <code>removeAttributes(":all", "class")</code>.
332	     </p>
333	
334	     @param tag  The tag the attributes are for.
335	     @param attributes List of invalid attributes for the tag
336	     @return this (for chaining)
337	     */
338	    public Safelist removeAttributes(String tag, String... attributes) {
339	        Validate.notEmpty(tag);
340	        Validate.notNull(attributes);
341	        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");
342	
343	        TagName tagName = TagName.valueOf(tag);
344	        Set<AttributeKey> attributeSet = new HashSet<>();
345	        for (String key : attributes) {
346	            Validate.notEmpty(key);
347	            attributeSet.add(AttributeKey.valueOf(key));
348	        }
349	        if(tagNames.contains(tagName) && this.attributes.containsKey(tagName)) { // Only look in sub-maps if tag was allowed
350	            Set<AttributeKey> currentSet = this.attributes.get(tagName);
351	            currentSet.removeAll(attributeSet);
352	
353	            if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
354	                this.attributes.remove(tagName);
355	        }
356	        if(tag.equals(All)) { // Attribute needs to be removed from all individually set tags
357	            Iterator<Map.Entry<TagName, Set<AttributeKey>>> it = this.attributes.entrySet().iterator();
358	            while (it.hasNext()) {
359	                Map.Entry<TagName, Set<AttributeKey>> entry = it.next();
360	                Set<AttributeKey> currentSet = entry.getValue();
361	                currentSet.removeAll(attributeSet);
362	                if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
363	                    it.remove();
364	            }
365	        }
366	        return this;
367	    }
