442	    /**
443	     Add allowed URL protocols for an element's URL attribute. This restricts the possible values of the attribute to
444	     URLs with the defined protocol.
445	     <p>
446	     E.g.: <code>addProtocols("a", "href", "ftp", "http", "https")</code>
447	     </p>
448	     <p>
449	     To allow a link to an in-page URL anchor (i.e. <code>&lt;a href="#anchor"&gt;</code>, add a <code>#</code>:<br>
450	     E.g.: <code>addProtocols("a", "href", "#")</code>
451	     </p>
452	
453	     @param tag       Tag the URL protocol is for
454	     @param attribute       Attribute name
455	     @param protocols List of valid protocols
456	     @return this, for chaining
457	     */
458	    public Safelist addProtocols(String tag, String attribute, String... protocols) {
459	        Validate.notEmpty(tag);
460	        Validate.notEmpty(attribute);
461	        Validate.notNull(protocols);
462	
463	        TagName tagName = TagName.valueOf(tag);
464	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
465	        Map<AttributeKey, Set<Protocol>> attrMap = this.protocols.computeIfAbsent(tagName, k -> new HashMap<>());
466	        Set<Protocol> protSet = attrMap.computeIfAbsent(attrKey, k -> new HashSet<>());
467	
468	        for (String protocol : protocols) {
469	            Validate.notEmpty(protocol);
470	            Protocol prot = Protocol.valueOf(protocol);
471	            protSet.add(prot);
472	        }
473	        return this;
474	    }
475	
476	    /**
477	     Remove allowed URL protocols for an element's URL attribute. If you remove all protocols for an attribute, that
478	     attribute will allow any protocol.
479	     <p>
480	     E.g.: <code>removeProtocols("a", "href", "ftp")</code>
481	     </p>
482	
483	     @param tag Tag the URL protocol is for
484	     @param attribute Attribute name
485	     @param removeProtocols List of invalid protocols
486	     @return this, for chaining
487	     */
488	    public Safelist removeProtocols(String tag, String attribute, String... removeProtocols) {
489	        Validate.notEmpty(tag);
490	        Validate.notEmpty(attribute);
491	        Validate.notNull(removeProtocols);
492	
493	        TagName tagName = TagName.valueOf(tag);
494	        AttributeKey attr = AttributeKey.valueOf(attribute);
495	
496	        // make sure that what we're removing actually exists; otherwise can open the tag to any data and that can
497	        // be surprising
498	        Validate.isTrue(protocols.containsKey(tagName), "Cannot remove a protocol that is not set.");
499	        Map<AttributeKey, Set<Protocol>> tagProtocols = protocols.get(tagName);
500	        Validate.isTrue(tagProtocols.containsKey(attr), "Cannot remove a protocol that is not set.");
501	
502	        Set<Protocol> attrProtocols = tagProtocols.get(attr);
503	        for (String protocol : removeProtocols) {
504	            Validate.notEmpty(protocol);
505	            attrProtocols.remove(Protocol.valueOf(protocol));
506	        }
507	
508	        if (attrProtocols.isEmpty()) { // Remove protocol set if empty
509	            tagProtocols.remove(attr);
510	            if (tagProtocols.isEmpty()) // Remove entry for tag if empty
511	                protocols.remove(tagName);
512	        }
513	        return this;
514	    }
