516	    /**
517	     * Test if the supplied tag is allowed by this safelist.
518	     * @param tag test tag
519	     * @return true if allowed
520	     */
521	    public boolean isSafeTag(String tag) {
522	        return tagNames.contains(TagName.valueOf(tag));
523	    }
524	
525	    /**
526	     * Test if the supplied attribute is allowed by this safelist for this tag.
527	     * <p>This method does not modify the input element or attribute.</p>
528	     * <p>Note that for {@code srcset} attributes, which hold a comma-separated list of URL candidates, this method
529	     * only tests that the attribute itself is allowed; the {@link Cleaner} validates each candidate URL against the
530	     * configured protocols when cleaning.</p>
531	     * @param tagName tag to consider allowing the attribute in
532	     * @param el element under test, to confirm protocol
533	     * @param attr attribute under test
534	     * @return true if allowed
535	     */
536	    public boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
537	        TagName tag = TagName.valueOf(tagName);
538	        AttributeKey key = AttributeKey.valueOf(attr.getKey());
539	
540	        Set<AttributeKey> okSet = attributes.get(tag);
541	        if (okSet != null && okSet.contains(key)) {
542	            if (protocols.containsKey(tag)) {
543	                Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
544	                // ok if not defined protocol; otherwise test. srcset URLs are tested per candidate in the Cleaner.
545	                return !attrProts.containsKey(key) || isSrcset(attr.getKey())
546	                    || (isSoundUrlValue(attr.getValue())
547	                        && isSafeProtocol(getProtocolValue(el, attr), attrProts.get(key)));
548	            } else { // attribute found, no protocols defined, so OK
549	                return true;
550	            }
551	        }
552	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
553	        if (enforcedSet != null && enforcedSet.containsKey(key)) {
554	            // enforced attr key was LCed via AttributeKey.valueOf(attr.getKey()),
555	            // if the input already has that exact value, treat it as safe
556	            return enforcedSet.get(key).equals(AttributeValue.valueOf(attr.getValue()));
557	        }
558	        // no attributes defined for tag, try :all tag
559	        return !tagName.equals(All) && isSafeAttribute(All, el, attr);
560	    }
561	
562	    private String getProtocolValue(Element el, Attribute attr) {
563	        String value = el.absUrl(attr.getKey());
564	        if (value.isEmpty() && !StringUtil.hasHttpScheme(attr.getValue()))
565	            value = attr.getValue(); // if it could not be made abs, run as-is to allow custom unknown protocols
566	        return value;
567	    }
568	
569	    private static final Pattern BareScheme = Pattern.compile("^[a-zA-Z][a-zA-Z0-9+-.]*:$");
570	
571	    /**
572	     Tests if a single-value URL attribute value is structurally sound for protocol validation. Empty and
573	     whitespace-only values are left to the standard resolution rules. Otherwise, the value must not contain control
574	     characters or whitespace, and must not be a bare scheme (e.g. {@code "mailto:"}) with no content after the
575	     colon.
576	     */
577	    private static boolean isSoundUrlValue(String value) {
578	        if (StringUtil.isBlank(value)) return true; // blank values follow the standard resolution rules
579	        for (int i = 0, length = value.length(); i < length; i++) {
580	            char c = value.charAt(i);
581	            if (c <= 0x20 || c == 0x7f) return false; // control character or whitespace within the URL
582	        }
583	        return !BareScheme.matcher(value).matches();
584	    }
585	
586	    private boolean isSafeProtocol(String value, Set<Protocol> protocols) {
587	        for (Protocol protocol : protocols) {
588	            String prot = protocol.toString();
589	
590	            if (prot.equals("#")) { // allows anchor links
591	                if (isValidAnchor(value)) {
592	                    return true;
593	                } else {
594	                    continue;
595	                }
596	            }
597	
598	            String lc = lowerCase(value);
599	            if (lc.startsWith(prot)
600	                && lc.length() > prot.length()
601	                && lc.charAt(prot.length()) == ':') {
602	                return true;
603	            }
604	        }
605	        return false;
606	    }
607	
608	    /**
609	     Tests if the attribute is {@code srcset} (case-insensitive), which holds a comma-separated list of image
610	     candidate URLs and so gets per-candidate cleaning in the {@link Cleaner}.
611	     */
612	    static boolean isSrcset(String attrKey) {
613	        return attrKey.equalsIgnoreCase(Srcset);
614	    }
615	
616	    /**
617	     Cleans a {@code srcset} attribute value, candidate by candidate. Candidates with invalid syntax (missing URL,
618	     empty candidates, malformed descriptors, or trailing junk) are dropped, as are those whose URL fails the
619	     protocol checks configured for the attribute on this tag. Surviving candidates keep their original order and
620	     are normalized to {@code url descriptor, url descriptor} form. Does not throw on malformed input.
621	
622	     @param tagName the tag the attribute is on; selects the applicable protocol configuration
623	     @param el the element the attribute is on, to resolve URLs against its base URI
624	     @param value the source srcset attribute value
625	     @return the cleaned value, or {@code null} if no candidates survive (in which case the attribute is removed)
626	     */
627	    String cleanSrcset(String tagName, Element el, String value) {
628	        Set<Protocol> protocols = srcsetProtocols(TagName.valueOf(tagName));
629	        StringBuilder sb = StringUtil.borrowBuilder();
630	
631	        int pos = 0, length = value.length();
632	        while (pos <= length) {
633	            // find the end of this candidate: a comma separates candidates, unless it is within the URL and directly
634	            // followed by a non-whitespace, non-comma character (e.g. the comma in a data: URL). Consecutive
635	            // separators produce empty candidates, which are invalid.
636	            int start = pos, end = pos;
637	            boolean inUrl = true; // still scanning the URL run (no whitespace after URL content yet)
638	            boolean started = false; // seen non-whitespace content in this candidate
639	            while (end < length) {
640	                char c = value.charAt(end);
641	                if (c == ',') {
642	                    if (inUrl && started && end + 1 < length && !isSrcsetSpace(value.charAt(end + 1)) && value.charAt(end + 1) != ',')
643	                        end++; // comma is part of the URL
644	                    else
645	                        break; // candidate separator
646	                } else {
647	                    if (isSrcsetSpace(c)) {
648	                        if (started) inUrl = false;
649	                    } else {
650	                        started = true;
651	                    }
652	                    end++;
653	                }
654	            }
655	            appendSrcsetCandidate(el, value, start, end, protocols, sb);
656	            if (end >= length) break;
657	            pos = end + 1; // step past the separator comma
658	        }
659	
660	        if (sb.length() == 0) {
661	            StringUtil.releaseBuilderVoid(sb);
662	            return null;
663	        }
664	        return StringUtil.releaseBuilder(sb);
665	    }
666	
667	    /**
668	     Validates and appends a single srcset candidate (the {@code value} range {@code start}..{@code end}) to
669	     {@code sb}. Invalid or unsafe candidates are silently dropped; their text is never recombined into new URLs.
670	     */
671	    private void appendSrcsetCandidate(Element el, String value, int start, int end, Set<Protocol> protocols, StringBuilder sb) {
672	        // trim ASCII whitespace from the candidate
673	        while (start < end && isSrcsetSpace(value.charAt(start))) start++;
674	        while (end > start && isSrcsetSpace(value.charAt(end - 1))) end--;
675	        if (start == end) return; // empty candidate (e.g. from consecutive separators)
676	
677	        // the URL is the leading run of non-whitespace
678	        int urlEnd = start;
679	        while (urlEnd < end && !isSrcsetSpace(value.charAt(urlEnd))) urlEnd++;
680	        String url = value.substring(start, urlEnd);
681	
682	        // an optional descriptor may follow, introduced by at least one ASCII space
683	        String descriptor = null;
684	        if (urlEnd < end) {
685	            if (value.charAt(urlEnd) != ' ') return; // the descriptor must be space-separated from the URL
686	            int descStart = urlEnd;
687	            while (descStart < end && value.charAt(descStart) == ' ') descStart++;
688	            int descEnd = descStart;
689	            while (descEnd < end && !isSrcsetSpace(value.charAt(descEnd))) descEnd++;
690	            if (descEnd != end) return; // unexpected content after the descriptor (e.g. a second descriptor)
691	            descriptor = value.substring(descStart, descEnd);
692	            if (!isValidSrcsetDescriptor(descriptor)) return;
693	        }
694	
695	        if (protocols != null && !isSafeSrcsetUrl(el, url, protocols)) return;
696	
697	        if (sb.length() > 0) sb.append(", ");
698	        sb.append(url);
699	        if (descriptor != null) sb.append(' ').append(descriptor);
700	    }
701	
702	    /**
703	     Finds the protocol configuration applicable to {@code srcset} on the given tag, following the same tag to
704	     {@code :all} fallback as {@link #isSafeAttribute}, so that per-tag differences neither widen nor narrow each
705	     other. Returns {@code null} when URLs are unrestricted.
706	     */
707	    private Set<Protocol> srcsetProtocols(TagName tag) {
708	        Set<AttributeKey> okSet = attributes.get(tag);
709	        if (okSet != null && okSet.contains(SrcsetKey)) {
710	            Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
711	            return attrProts != null ? attrProts.get(SrcsetKey) : null;
712	        }
713	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
714	        if (enforcedSet != null && enforcedSet.containsKey(SrcsetKey)) return null;
715	        return !tag.equals(AllTag) ? srcsetProtocols(AllTag) : null;
716	    }
717	
718	    private boolean isSafeSrcsetUrl(Element el, String url, Set<Protocol> protocols) {
719	        String value = StringUtil.resolve(el.baseUri(), url);
720	        if (value.isEmpty() && !StringUtil.hasHttpScheme(url))
721	            value = url; // if it could not be made absolute, run as-is to allow custom unknown protocols
722	        return isSafeProtocol(value, protocols);
723	    }
724	
725	    /**
726	     Validates a srcset descriptor: a positive integer followed by a lowercase {@code w} (e.g. {@code 100w}), or a
727	     positive number (digits, or digits.digits) followed by a lowercase {@code x} (e.g. {@code 2x}, {@code 1.5x}).
728	     Signs, exponents, a dot missing a side, and zero values are all invalid.
729	     */
730	    private static boolean isValidSrcsetDescriptor(String descriptor) {
731	        int length = descriptor.length();
732	        if (length < 2) return false;
733	        String number = descriptor.substring(0, length - 1);
734	        switch (descriptor.charAt(length - 1)) {
735	            case 'w': return isPositiveInteger(number);
736	            case 'x': return isPositiveNumber(number);
737	            default:  return false;
738	        }
739	    }
740	
741	    /** Tests if the value is all digits and greater than zero. */
742	    private static boolean isPositiveInteger(String number) {
743	        boolean nonZero = false;
744	        for (int i = 0, length = number.length(); i < length; i++) {
745	            char c = number.charAt(i);
746	            if (c < '0' || c > '9') return false;
747	            if (c != '0') nonZero = true;
748	        }
749	        return nonZero;
750	    }
751	
752	    /** Tests if the value is digits, or digits.digits, and greater than zero. */
753	    private static boolean isPositiveNumber(String number) {
754	        int dot = number.indexOf('.');
755	        if (dot == -1) return isPositiveInteger(number);
756	        if (number.indexOf('.', dot + 1) != -1) return false; // at most one dot
757	        String integer = number.substring(0, dot);
758	        String fraction = number.substring(dot + 1);
759	        if (!isDigits(integer) || !isDigits(fraction)) return false; // the dot needs digits on both sides
760	        return isPositiveInteger(integer) || isPositiveInteger(fraction);
761	    }
762	
763	    private static boolean isDigits(String value) {
764	        for (int i = 0, length = value.length(); i < length; i++) {
765	            char c = value.charAt(i);
766	            if (c < '0' || c > '9') return false;
767	        }
768	        return value.length() > 0;
769	    }
770	
771	    /** The ASCII whitespace characters: space, tab, newline, carriage return, and form feed. */
772	    private static boolean isSrcsetSpace(char c) {
773	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
774	    }
775	
776	    /**
777	     Check if a URL attribute should be normalized to an absolute URL in the cleaned output. Uses the configured
778	     protocols for that tag+attribute pair, falling back to {@code :all} only if the tag does not define the
779	     attribute.
780	     */
781	    boolean shouldAbsUrl(String tagName, String attrKey) {
782	        if (preserveRelativeLinks) return false;
783	        return shouldAbsUrl(TagName.valueOf(tagName), AttributeKey.valueOf(attrKey));
784	    }
785	
786	    private boolean shouldAbsUrl(TagName tag, AttributeKey key) {
787	        Set<AttributeKey> allowedAttrs = attributes.get(tag);
788	        if (allowedAttrs != null && allowedAttrs.contains(key)) {
789	            Map<AttributeKey, Set<Protocol>> protocolsByAttr = protocols.get(tag);
790	            return protocolsByAttr != null && protocolsByAttr.containsKey(key);
791	        }
792	
793	        Map<AttributeKey, AttributeValue> enforcedAttrs = enforcedAttributes.get(tag);
794	        if (enforcedAttrs != null && enforcedAttrs.containsKey(key)) return false;
795	
796	        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
797	    }
798	
799	    private static boolean isValidAnchor(String value) {
800	        return value.startsWith("#") && !value.matches(".*\\s.*");
801	    }
802	
803	    /**
804	     Gets the Attributes that should be enforced for a given tag
805	     * @param tagName the tag
806	     * @return the attributes that will be enforced; empty if none are set for the given tag
807	     */
808	    public Attributes getEnforcedAttributes(String tagName) {
809	        Attributes attrs = new Attributes();
810	        TagName tag = TagName.valueOf(tagName);
811	        if (enforcedAttributes.containsKey(tag)) {
812	            Map<AttributeKey, AttributeValue> keyVals = enforcedAttributes.get(tag);
813	            for (Map.Entry<AttributeKey, AttributeValue> entry : keyVals.entrySet()) {
814	                attrs.put(entry.getKey().toString(), entry.getValue().toString());
815	            }
816	        }
817	        return attrs;
818	    }
819	    
820	    // named types for config. All just hold strings, but here for my sanity.
821	
822	    static class TagName extends TypedValue {
823	        TagName(String value) {
824	            super(value);
825	        }
826	
827	        static TagName valueOf(String value) {
828	            return new TagName(Normalizer.lowerCase(value));
829	        }
830	    }
831	
832	    static class AttributeKey extends TypedValue {
833	        AttributeKey(String value) {
834	            super(value);
835	        }
836	
837	        static AttributeKey valueOf(String value) {
838	            return new AttributeKey(Normalizer.lowerCase(value));
839	        }
840	    }
841	
842	    static class AttributeValue extends TypedValue {
843	        AttributeValue(String value) {
844	            super(value);
845	        }
846	
847	        static AttributeValue valueOf(String value) {
848	            return new AttributeValue(value);
849	        }
850	    }
851	
852	    static class Protocol extends TypedValue {
853	        Protocol(String value) {
854	            super(value);
855	        }
856	
857	        static Protocol valueOf(String value) {
858	            return new Protocol(value);
859	        }
860	    }
861	
862	    abstract static class TypedValue {
863	        private final String value;
864	
865	        TypedValue(String value) {
866	            Validate.notNull(value);
867	            this.value = value;
868	        }
869	
870	        @Override
871	        public int hashCode() {
872	            return value.hashCode();
873	        }
874	
875	        @Override
876	        public boolean equals(Object obj) {
877	            if (this == obj) return true;
878	            if (obj == null || getClass() != obj.getClass()) return false;
879	            TypedValue other = (TypedValue) obj;
880	            return Objects.equals(value, other.value);
881	        }
882	
883	        @Override
884	        public String toString() {
885	            return value;
886	        }
887	    }
888	}
