import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Safelist;

public class P14 {
    static Safelist pol(boolean rel){ return Safelist.basicWithImages().addAttributes("img","srcset")
        .addProtocols("img","srcset","http","https").preserveRelativeLinks(rel); }
    static void run(String label, boolean rel, String val, String base){
        try {
            Safelist sl = pol(rel);
            Document dirty = Jsoup.parse("<img srcset='"+val+"'>", base);
            String raw = dirty.select("img").attr("srcset");
            Document clean = new Cleaner(sl).clean(dirty);
            String out = clean.body().html();
            boolean mutated = !dirty.select("img").attr("srcset").equals(raw);
            // idempotency
            Document clean2 = new Cleaner(sl).clean(clean);
            boolean stable = clean.body().html().equals(clean2.body().html());
            System.out.println(label.padEnd(26)+" mut="+mutated+" stable="+stable+"  "+out.replace("\u007f","<D>").replace("\u0001","<1>"));
        } catch(Throwable t){ System.out.println(label+" THREW "+t); }
    }
    public static void main(String[] a){
        String base="https://example.com/page/index.html";
        run("pct-js", false, "java%73cript:alert(1) 1x, https://ok.com/b.jpg 2x", base);
        run("pct-js-firstchar", false, "%6Aavascript:x, https://ok.com/b.jpg", base);
        run("pct-colon-js", false, "javascript%3Aalert(1), https://ok.com/b.jpg", base);
        run("pct-nul-js", false, "%00javascript:x, https://ok.com/b.jpg", base);
        run("DEL-js", false, "java\u007fscript:x 1x, https://ok.com/b.jpg 2x", base);
        run("SOH-js", false, "java\u0001script:x, https://ok.com/b.jpg", base);
        run("case-js", false, "JaVaScRiPt:x, https://ok.com/b.jpg", base);
        run("proto-rel https base", false, "//evil.com/a.jpg 1x, https://ok.com/b.jpg 2x", base);
        run("proto-rel relative-keep", true, "//evil.com/a.jpg, /b.jpg", base);
        run("relative abs-mode", false, "a.jpg, ../b.jpg, https://ok.com/c.jpg", base);
        run("relative keep-mode", true, "a.jpg, ../b.jpg, https://ok.com/c.jpg", base);
        run("benign pct path", true, "images/a%20b%2Ejpg, https://ok.com/c.jpg", base);
        run("benign pct in http", false, "https://ok.com/a%2Cb%20c.jpg, https://ok.com/d.jpg", base);
        run("pct colon in path", true, "x%3Ay.jpg, https://ok.com/b.jpg", base);
        run("data blocked", false, "data:image/png;base64,AAAA, https://ok.com/b.jpg", base);
        run("leading ws js", false, "  javascript:x, https://ok.com/b.jpg", base);
        run("encoded tab sep", false, "https://ok.com/a.jpg&#x09;1x", base);
        run("multi independent", false, "https://ok.com/a.jpg", base);
        run("empty base relative", false, "a.jpg, https://ok.com/b.jpg", "");
    }
}
